class DSU:
    def __init__(self, n):

        # initially each node is its own parent
        self.p = list(range(n))
        self.r = [0] * n

    # path compression
    def find(self, x):
        if self.p[x] == x:
            return x
        self.p[x] = self.find(self.p[x])
        return self.p[x]

    def unite(self, a, b):
        a = self.find(a)
        b = self.find(b)

        # already connected
        if a == b:
            return False

        # union by rank
        if self.r[a] < self.r[b]:
            a, b = b, a

        self.p[b] = a
        if self.r[a] == self.r[b]:
            self.r[a] += 1

        return True


